test.describe('Regression', () => {
  test('User can place order for a product', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await expect(page.getByText('Swag Labs')).toBeVisible();
    await page.locator('[data-test="username"]').click();
    await page.locator('[data-test="username"]').fill('<redacted>');
    await page.locator('[data-test="username"]').press('Tab');
    await page.locator('[data-test="password"]').fill('<redacted>');
    await page.locator('[data-test="login-button"]').click();
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await page.locator('[data-test="product-sort-container"]').selectOption('za');
    await expect(page.locator('[data-test="item-1-title-link"] [data-test="inventory-item-name"]')).toContainText('Sauce Labs Bolt T-Shirt');
    await expect(page.locator('[data-test="inventory-list"]')).toContainText('$15.99');
    await page.locator('[data-test="add-to-cart-sauce-labs-bolt-t-shirt"]').click();
    await page.locator('[data-test="shopping-cart-link"]').click();
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await expect(page.locator('[data-test="inventory-item-name"]')).toContainText('Sauce Labs Bolt T-Shirt');
    await expect(page.locator('[data-test="inventory-item-price"]')).toContainText('$15.99');
    await page.locator('[data-test="checkout"]').click();
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await page.locator('[data-test="firstName"]').click();
    await page.locator('[data-test="firstName"]').fill('<redacted>');
    await page.locator('[data-test="firstName"]').press('Tab');
    await page.locator('[data-test="lastName"]').fill('<redacted>');
    await page.locator('[data-test="lastName"]').press('Tab');
    await page.locator('[data-test="postalCode"]').fill('<redacted>');
    await page.locator('[data-test="continue"]').click();
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await expect(page.locator('[data-test="inventory-item-name"]')).toContainText('Sauce Labs Bolt T-Shirt');
    await expect(page.locator('[data-test="inventory-item-price"]')).toContainText('$15.99');
    await page.locator('[data-test="finish"]').click();
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await expect(page.locator('[data-test="complete-header"]')).toBeVisible();
  });
});

